sp_widget.css:
.hero-section {
  padding-top: 25px;

  .hero-banner {
    background: linear-gradient(135deg, #00695C, #004D40);
    border-radius: 12px;
    padding: 60px 40px;
    text-align: center;
    margin-bottom: 30px;

    .hero-content {
      h1 {
        color: white;
        font-size: 36px;
        font-weight: bold;
        margin-bottom: 15px;
      }

      p {
        color: #B2DFDB;
        font-size: 18px;
        margin-bottom: 25px;
      }

      .btn-hero {
        background: white;
        color: #00695C;
        border-radius: 25px;
        padding: 12px 35px;
        font-weight: bold;
        font-size: 16px;
        text-decoration: none;

        &:hover {
          background: #E0F2F1;
        }
      }
    }
  }

  .stats-row {
    display: flex;
    gap: 20px;
    margin-bottom: 30px;

    .stat-card {
      flex: 1;
      background: white;
      border-radius: 12px;
      padding: 25px;
      text-align: center;
      box-shadow: 0 2px 8px rgba(0,0,0,0.08);
      border-top: 4px solid #00695C;

      h2 {
        color: #00695C;
        font-size: 36px;
        font-weight: bold;
        margin-bottom: 5px;
      }

      p {
        color: #666;
        margin: 0;
        font-size: 14px;
      }
    }
  }

  .quick-links {
    h3 {
      color: #333;
      font-weight: bold;
      margin-bottom: 15px;
    }

    .links-grid {
      display: flex;
      gap: 15px;

      .quick-link-card {
        flex: 1;
        background: white;
        border-radius: 12px;
        padding: 25px;
        text-align: center;
        box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        text-decoration: none;
        transition: transform 0.2s ease;

        &:hover {
          transform: translateY(-3px);
          box-shadow: 0 6px 16px rgba(0,0,0,0.12);
        }

        p {
          color: #333;
          font-weight: bold;
          margin-top: 10px;
          margin-bottom: 0;
        }
      }
    }
  }
}

sp_widget.script:
(function() {
    // Total halls
    var halls = new GlideAggregate(
        'x_1954179_sports_0_sports_hall'
    );
    halls.addAggregate('COUNT');
    halls.query();
    data.totalHalls = 0;
    if (halls.next()) {
        data.totalHalls = halls.getAggregate('COUNT');
    }

    // Available halls
    var available = new GlideAggregate(
        'x_1954179_sports_0_sports_hall'
    );
    available.addQuery('available', true);
    available.addAggregate('COUNT');
    available.query();
    data.availableHalls = 0;
    if (available.next()) {
        data.availableHalls = available.getAggregate('COUNT');
    }

    // Total bookings
    var bookings = new GlideAggregate(
        'x_1954179_sports_0_sports_hall_booking'
    );
    bookings.addAggregate('COUNT');
    bookings.query();
    data.totalBookings = 0;
    if (bookings.next()) {
        data.totalBookings = bookings.getAggregate('COUNT');
    }
})();
